command:
$ErrorActionPreference = 'Stop'
$branch = 'issue-502-quality-retry-merge'
$expectedHead = '4a54152636f5a9111c79334a3f5e82fe8d5d5137'
$expectedValidationCount = 50
function Invoke-Git([string[]]$GitArgs) {
  Write-Host "git $($GitArgs -join ' ')"
  $output = & git @GitArgs
  $code = $LASTEXITCODE
  if ($output) { $output | Out-Host }
  if ($code -ne 0) { throw "git failed with exit $code`: git $($GitArgs -join ' ')" }
}
Invoke-Git @('fetch', '--no-tags', 'origin', "refs/heads/$branch`:refs/remotes/origin/$branch")
$remoteHead = (& git rev-parse "refs/remotes/origin/$branch").Trim()
if ($LASTEXITCODE -ne 0) { throw 'Unable to read remote branch head.' }
if ($remoteHead -ne $expectedHead) { throw "PR head drifted: expected $expectedHead got $remoteHead" }
$worktree = Join-Path $env:RUNNER_TEMP 'issue502_pr503_full_governed_validation_v3'
if (Test-Path -LiteralPath $worktree) { Remove-Item -LiteralPath $worktree -Recurse -Force }
Invoke-Git @('worktree', 'prune')
Invoke-Git @('worktree', 'add', '--detach', $worktree, $remoteHead)
try {
  Push-Location $worktree
  @('OPENROUTER_API_KEY','DCOIR_OPENROUTER_API_KEY','OPENROUTER_MANAGEMENT_KEY','OPENAI_API_KEY','DCOIR_OPENAI_API_KEY','DCOIR_OPENAI_PROJECT_ID','DCOIR_GEMINI_API','DCOIR_GEMINI_API_KEY','GEMINI_API_KEY','GOOGLE_API_KEY') | ForEach-Object { [Environment]::SetEnvironmentVariable($_, $null, 'Process') }
  $env:PYTHONDONTWRITEBYTECODE = '1'
  $commands = @()
  $capturing = $false
  foreach ($line in Get-Content -LiteralPath '.github/dcoir_review/openrouter-pr-review-pareto.yml' -Encoding UTF8) {
    if ($line -match '^validation_commands:\s*$') { $capturing = $true; continue }
    if (-not $capturing) { continue }
    if ($line -match '^\s{2}-\s+(.+?)\s*$') { $commands += $Matches[1]; continue }
    if ($line -match '^\S') { break }
  }
  if ($commands.Count -ne $expectedValidationCount) { throw "expected $expectedValidationCount governed validation commands, parsed $($commands.Count)" }
  $index = 0
  foreach ($command in $commands) {
    $index++
    Write-Host "[$index/$expectedValidationCount] $command"
    & cmd.exe /d /s /c $command
    if ($LASTEXITCODE -ne 0) { throw "validation command $index failed with exit code $LASTEXITCODE`: $command" }
  }
  Invoke-Git @('diff', '--check', 'HEAD^', 'HEAD')
  $dirty = @(& git status --porcelain=v1 --untracked-files=all)
  if ($dirty.Count -gt 0) { throw "validation dirtied detached worktree: $($dirty -join '; ')" }
  $actualHead = (& git rev-parse HEAD).Trim()
  if ($actualHead -ne $expectedHead) { throw "Validated wrong head: $actualHead" }
  Write-Host ('ISSUE502_PR503_GOVERNED_VALIDATION=PASS:' + $actualHead + ':' + $commands.Count)
} finally {
  Pop-Location -ErrorAction SilentlyContinue
  & git worktree remove --force $worktree 2>$null
  & git worktree prune 2>$null
}
